def applyShifts(s, shifts):
    n = len(s)
    diff = [0] * (n + 1)
    for left, right, d in shifts:
        step = 1 if d == 1 else -1
        diff[left] += step
        diff[right + 1] -= step
    out = []
    run = 0
    for i in range(n):
        run += diff[i]
        out.append(chr((ord(s[i]) - 97 + run) % 26 + 97))
    return "".join(out)
